class InboundInvoiceItem {
  constructor(
    id,
    product,
    product_title,
    purchased_unit_quantity,
    bonus_unit_quantity,
    pack_buying_price,
    pack_selling_price,
    percent_discount,
    manufacture_date,
    item_total_value,
    expiry_date,
    batch

  ) {
    this.id = id;
    this.product = product;
    this.product_title = product_title;
    this.purchased_unit_quantity = purchased_unit_quantity;
    this.bonus_unit_quantity = bonus_unit_quantity;
    this.pack_buying_price = pack_buying_price;
    this.pack_selling_price = pack_selling_price;
    this.percent_discount = percent_discount;
    this.manufacture_date = manufacture_date;
    this.item_total_value = item_total_value;
    this.expiry_date = expiry_date;
    this.batch = batch;

  }
}

export default InboundInvoiceItem;
